/**
 * Truck settings library — URL-based preset definitions.
 *
 * Library entries are defined as share URLs (generated by the "Share current" button).
 * This allows easy copy-paste of configured setups into the library.
 *
 * To add a new entry:
 * 1. Configure the setup in the app
 * 2. Click "Share current" to get a URL
 * 3. Copy the URL into the LIBRARY array below
 */

import type { BoardSetupConfig } from './BoardSetupConfig'
import { deserializeState } from '../utils/urlState'

/** A library entry: a label and the share URL that defines the setup. */
export interface LibraryEntry {
  label: string
  /** Full share URL (e.g. "https://example.com?setup=...") or just the encoded part after "?setup=" */
  url: string
}

/**
 * The truck settings library.
 *
 * Each entry's URL encodes a full app state. The first setup in the URL
 * is used as the preset configuration.
 *
 * To generate a URL: configure a setup, click "Share current", copy the link.
 */
export const LIBRARY: LibraryEntry[] = [
  {
    label: 'Standard RKP 50°',
    url: '?',
  },
  {
    label: 'Standard TKP',
    url: '?',
  },
  {
    label: 'High-angle RKP 65°',
    url: '?',
  },
  {
    label:'Long Distance Pumper',
    url: '?'
  }
]

/**
 * Extract the first setup configuration from a library entry URL.
 *
 * @param entry - The library entry containing the URL.
 * @returns The BoardSetupConfig, or null if the URL is invalid.
 */
export function getSetupFromLibraryEntry(entry: LibraryEntry): Omit<BoardSetupConfig, 'id' | 'name' | 'color'> | null {
  // Extract the encoded part from the URL (after "?setup=")
  const match = entry.url.match(/[?&]setup=([^&]+)/)
  if (!match) return null

  const encoded = match[1]
  const state = deserializeState(encoded)
  if (!state || state.setups.length === 0) return null

  // Return the first setup without id, name, color (those will be assigned when instantiated)
  const { id: _id, name: _name, color: _color, ...config } = state.setups[0]
  return config
}
